 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Every nonzero input cell expands into a tile showing the complement of
    # the input's colored-cell pattern. Use binary occupancy for the motif and
    # preserve the cell's original color in the expanded output.
    motif = [[0 if grid[r][c] else 1 for c in range(w)] for r in range(h)]
    out = [[0 for _ in range(3 * w)] for _ in range(3 * h)]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color:
                for dr in range(h):
                    for dc in range(w):
                        if motif[dr][dc]:
                            out[r * h + dr][c * w + dc] = color
    return out

